const board = document.getElementById("board");
const pen = board.getContext("2d");
pen.lineWidth = 6;
pen.lineCap = "round";
let drawing = false;
const colour = () => document.getElementById("colour").value;
const erasing = () => document.getElementById("eraser").checked;
board.addEventListener("pointerdown", (event) => {
  drawing = true;
  pen.beginPath();
  pen.moveTo(event.offsetX, event.offsetY);
});
board.addEventListener("pointermove", (event) => {
  if (!drawing) return;
  pen.strokeStyle = erasing() ? "#ffffff" : colour();
  pen.lineTo(event.offsetX, event.offsetY);
  pen.stroke();
});
board.addEventListener("pointerup", () => (drawing = false));
